 155		canonical, err := checkpoint.CanonicalizeBatchSessions(req)
 156		if err != nil {
 157			return fmt.Errorf("fsstore: validate batch: %w", err)
 158		}
 159		sc, err := s.load(canonical.CheckpointID)
 160		if err != nil {
 161			return err
 162		}
 163		if sc == nil {
 164			sc = &storedCheckpoint{Summary: cp.CheckpointSummary{CheckpointID: canonical.CheckpointID}}
 165		}
 166	
 167		for _, reserved := range canonical.Sessions {
 168			opts := cp.WriteOptions(reserved)
 169			session := storedSession{
 170				SessionID:  opts.SessionID,
 171				Metadata:   metadataFromWriteOptions(opts),
 172				Transcript: opts.Transcript.Bytes(),
 173				Prompts:    checkpoint.RedactedJoinedPrompts(opts.Prompts),
 174			}
 175			sc.Sessions = upsertSession(sc.Sessions, session)
 176			sc.Summary.HasReview = sc.Summary.HasReview || opts.HasReview
 177			sc.Summary.HasInvestigation = sc.Summary.HasInvestigation || opts.HasInvestigation
 178		}
 179		recomputeSummary(sc)
 180		return s.save(sc)
 181	}
 182	
 183	func (s *Store) backfillTranscript(opts cp.UpdateOptions) error {
 184		sc, err := s.load(opts.CheckpointID)
 185		if err != nil {
 186			return err
 187		}
 188		if sc == nil {
 189			return fmt.Errorf("fsstore: cannot backfill transcript for unknown checkpoint %s", opts.CheckpointID)
 190		}
 191		idx := sessionIndexByID(sc.Sessions, opts.SessionID)
 192		if idx < 0 {
 193			return fmt.Errorf("fsstore: cannot backfill transcript for unknown session %q in %s", opts.SessionID, opts.CheckpointID)
 194		}
 195		// Replace semantics, but do not clobber sibling fields (matches the git
 196		// store's stop-time transcript backfill).
 197		sc.Sessions[idx].Transcript = opts.Transcript.Bytes()
 198		sc.Sessions[idx].Prompts = checkpoint.RedactedJoinedPrompts(opts.Prompts)
 199		if len(opts.SkillEvents) > 0 {
 200			sc.Sessions[idx].Metadata.SkillEvents = opts.SkillEvents
 201		}
 202		return s.save(sc)
 203	}
 204	
 205	func (s *Store) writeSessionSummary(r cp.SessionSummary) error {
 206		sc, err := s.load(r.CheckpointID)
 207		if err != nil {
 208			return err
 209		}
 210		if sc == nil || len(sc.Sessions) == 0 {
 211			return fmt.Errorf("fsstore: cannot set summary for unknown checkpoint %s", r.CheckpointID)
 212		}
 213		targetSessionID := r.SessionID
 214		if targetSessionID == "" {
 215			targetSessionID = sc.Sessions[len(sc.Sessions)-1].SessionID
 216		}
 217		idx := sessionIndexByID(sc.Sessions, targetSessionID)
 218		if idx < 0 {
 219			return &checkpoint.SessionNotFoundError{CheckpointID: r.CheckpointID, SessionID: targetSessionID}
 220		}
 221		sc.Sessions[idx].Metadata.Summary = checkpoint.RedactSummary(r.Summary)
 222		return s.save(sc)
 223	}
 224	
 225	func (s *Store) writeAttribution(r cp.CheckpointAttribution) error {
 226		sc, err := s.load(r.CheckpointID)
 227		if err != nil {
 228			return err
 229		}
 230		if sc == nil {
 231			return fmt.Errorf("fsstore: cannot set attribution for unknown checkpoint %s", r.CheckpointID)
 232		}
 233		sc.Summary.CombinedAttribution = r.Attribution
 234		return s.save(sc)
 235	}
 236	
 237	// Read returns the checkpoint summary, or (nil, nil) when absent so the
 238	// contract helper normalizes it to ErrCheckpointNotFound.
 239	func (s *Store) Read(_ context.Context, checkpointID id.CheckpointID) (*cp.CheckpointSummary, error) {
 240		s.mu.Lock()
 241		defer s.mu.Unlock()
 242		sc, err := s.load(checkpointID)
 243		if err != nil || sc == nil {
 244			return nil, err
 245		}

