401	func writePreparedBatch(ctx context.Context, writer batchRefWriter, prepared *preparedBatchSessions) error {
402		refName, err := writer.batchRefName(prepared.request.CheckpointID)
403		if err != nil {
404			return err
405		}
406		if err := writer.prepareBatchRef(ctx); err != nil {
407			return err
408		}
409		_, err = RunRefTransaction(ctx, writer.batchRepo(), refName, func(parentHash plumbing.Hash) (plumbing.Hash, bool, error) {
410			commitHash, err := writer.buildPreparedBatchCommit(ctx, prepared, parentHash)
411			return commitHash, true, err
412		})
413		if err != nil {
414			return err
415		}
416		writer.afterBatchPublish(ctx, refName)
417		return nil
