628	func qualifySessionFilePaths(basePath string, index int, relative SessionFilePaths) SessionFilePaths {
629		qualify := func(value string) string {
630			if value == "" {
631				return ""
632			}
633			return "/" + checkpointSubtreePath(basePath, strconv.Itoa(index), strings.TrimPrefix(value, "/"))
634		}
635		return SessionFilePaths{
636			Metadata:          qualify(relative.Metadata),
637			Transcript:        qualify(relative.Transcript),
638			CompactTranscript: qualify(relative.CompactTranscript),
639			ContentHash:       qualify(relative.ContentHash),
640			Prompt:            qualify(relative.Prompt),
641			AssetsManifest:    qualify(relative.AssetsManifest),
642		}
643	}
644	
645	func storeTreeEntryMap(repo *git.Repository, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
646		ordered := make([]object.TreeEntry, 0, len(entries))
647		for name, entry := range entries {
648			entry.Name = name
649			ordered = append(ordered, entry)
650		}
651		sortTreeEntries(ordered)
652		return storeTree(repo, ordered)
653	}
654	
655	func buildBatchCommitMessage(req BatchSessions) string {
656		var message strings.Builder
657		fmt.Fprintf(&message, "Checkpoint: %s\n\n", req.CheckpointID)
658		if req.CommitSubject != "" {
659			message.WriteString(req.CommitSubject)
660			message.WriteString("\n\n")
661		}
662		for _, session := range req.Sessions {
663			fmt.Fprintf(&message, "%s: %s\n", trailers.SessionTrailerKey, WriteOptions(session).SessionID)
664		}
665		if value, common := commonBatchValue(req.Sessions, func(opts WriteOptions) string { return opts.Strategy }); common {
666			fmt.Fprintf(&message, "%s: %s\n", trailers.StrategyTrailerKey, value)
667		}
668		if value, common := commonBatchValue(req.Sessions, func(opts WriteOptions) string { return string(opts.Agent) }); common && value != "" {
669			fmt.Fprintf(&message, "%s: %s\n", trailers.AgentTrailerKey, value)
670		}
671		if value, common := commonBatchValue(req.Sessions, func(opts WriteOptions) string { return opts.EphemeralBranch }); common && value != "" {
672			fmt.Fprintf(&message, "%s: %s\n", trailers.EphemeralBranchTrailerKey, value)
673		}
674		return message.String()
675	}
676	
677	func commonBatchValue(sessions []ReservedSession, value func(WriteOptions) string) (string, bool) {
678		first := value(WriteOptions(sessions[0]))
679		for _, session := range sessions[1:] {
680			if value(WriteOptions(session)) != first {
681				return "", false
682			}
683		}
684		return first, true
685	}

