366	func (s *GitStore) buildPreparedAttributionCommit(ctx context.Context, checkpointID id.CheckpointID, attribution *Attribution, parentHash plumbing.Hash, authorName, authorEmail string) (plumbing.Hash, error) {
367		if parentHash.IsZero() {
368			return plumbing.ZeroHash, ErrCheckpointNotFound
369		}
370		rootTreeHash, err := s.rootTreeHashAt(parentHash)
371		if err != nil {
372			return plumbing.ZeroHash, err
373		}
374		existing, err := s.subtreeObjAt(rootTreeHash, checkpointID.Path())
375		if err != nil {
376			return plumbing.ZeroHash, err
377		}
378		checkpointSubtree, err := s.applyAttributionBackfill(ctx, existing, checkpointID.Path()+"/", attribution)
379		if err != nil {
380			return plumbing.ZeroHash, err
381		}
382		newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, checkpointID, checkpointSubtree)
383		if err != nil {
384			return plumbing.ZeroHash, err
385		}
386		return CreateCommit(ctx, s.repo, newTreeHash, parentHash, fmt.Sprintf("Update checkpoint summary for %s", checkpointID), authorName, authorEmail)
387	}
