389	func (s *gitRefsStore) buildPreparedAttributionCommit(ctx context.Context, checkpointID id.CheckpointID, attribution *Attribution, parentHash plumbing.Hash, authorName, authorEmail string) (plumbing.Hash, error) {
390		existing, err := s.checkpointTreeAt(parentHash, checkpointID)
391		if err != nil {
392			return plumbing.ZeroHash, err
393		}
394		checkpointSubtree, err := s.applyAttributionBackfill(ctx, existing, "", attribution)
395		if err != nil {
396			return plumbing.ZeroHash, err
397		}
