 46	type persistentRefWriter interface {
 47		batchRefName(checkpointID id.CheckpointID) (plumbing.ReferenceName, error)
 48		batchRepo() *git.Repository
 49		prepareBatchRef(ctx context.Context) error
 50		afterBatchPublish(ctx context.Context, refName plumbing.ReferenceName)
