655	func buildBatchCommitMessage(req BatchSessions) string {
656		var message strings.Builder
657		fmt.Fprintf(&message, "Checkpoint: %s\n\n", req.CheckpointID)
658		if req.CommitSubject != "" {
659			message.WriteString(req.CommitSubject)
660			message.WriteString("\n\n")
661		}
662		for _, session := range req.Sessions {
663			fmt.Fprintf(&message, "%s: %s\n", trailers.SessionTrailerKey, WriteOptions(session).SessionID)
664		}
665		if value, common := commonBatchValue(req.Sessions, func(opts WriteOptions) string { return opts.Strategy }); common {
666			fmt.Fprintf(&message, "%s: %s\n", trailers.StrategyTrailerKey, value)
667		}
668		if value, common := commonBatchValue(req.Sessions, func(opts WriteOptions) string { return string(opts.Agent) }); common && value != "" {
669			fmt.Fprintf(&message, "%s: %s\n", trailers.AgentTrailerKey, value)
670		}
