 		Name:  authorName,
 		Email: authorEmail,
 		When:  now,
 	}

 	commit := &object.Commit{
 		TreeHash:  emptyTreeHash,
 		Author:    sig,
 		Committer: sig,
 		Message:   "Initialize metadata ref\n\nThis ref stores session metadata.\n",
