 	repo, err := OpenRepository(ctx)
 	if err != nil {
 		return fmt.Errorf("failed to open git repository: %w", err)
 	}
 	defer repo.Close()
 	return s.ensureSessionInitialized(ctx, repo, sessionID, agentType)
 }

