   780	// buildTreeWithChanges builds a git tree with the given changes.
   781	// metadataDir is the relative path for git tree entries, metadataDirAbs is the absolute path
   782	// for filesystem operations (needed when CLI is run from a subdirectory).
   783	//
   784	// Uses ApplyTreeChanges (tree surgery) instead of FlattenTree+BuildTreeFromEntries,
   785	// so only affected subtrees are read/rebuilt — O(changed dirs) instead of O(total files).
   786	func (s *ephemeralStore) buildTreeWithChanges(
   787		ctx context.Context,
   788		baseTreeHash plumbing.Hash,
   789		modifiedFiles, deletedFiles []string,
   790		metadataDir, metadataDirAbs string,
   791	) (plumbing.Hash, error) {
   792		// Get worktree root for resolving file paths
   793		// This is critical because fileExists() and createBlobFromFile() use os.Stat()
   794		// which resolves relative to CWD. The modifiedFiles are repo-relative paths,
   795		// so we must resolve them against repo root, not CWD.
   796		repoRoot, err := paths.WorktreeRoot(ctx)
   797		if err != nil {
   798			return plumbing.ZeroHash, fmt.Errorf("failed to get worktree root: %w", err)
   799		}
   800	
   801		// Build list of tree changes
   802		changes := make([]TreeChange, 0, len(modifiedFiles)+len(deletedFiles))
   803	
   804		// Deleted files → nil Entry means deletion
   805		for _, file := range deletedFiles {
   806			relPath, relErr := normalizeRepoRelativeTreePath(repoRoot, file)
   807			if relErr != nil {
   808				logInvalidGitTreePath(ctx, "delete shadow branch entry", file, relErr)
   809				continue
   810			}
   811			changes = append(changes, TreeChange{Path: relPath, Entry: nil})
   812		}
   813	
   814		// Modified/new files → create blobs from disk
   815		for _, file := range modifiedFiles {
   816			relPath, relErr := normalizeRepoRelativeTreePath(repoRoot, file)
   817			if relErr != nil {
   818				logInvalidGitTreePath(ctx, "add shadow branch entry", file, relErr)
   819				continue
   820			}
   821	
   822			absPath := filepath.Join(repoRoot, filepath.FromSlash(relPath))
   823			if !fileExists(absPath) {
   824				// File disappeared since detection — treat as deletion
   825				changes = append(changes, TreeChange{Path: relPath, Entry: nil})
   826				continue
   827			}
   828	
   829			blobHash, mode, blobErr := createBlobFromFile(s.repo, absPath)
   830			if blobErr != nil {
   831				// Skip files that can't be staged (may have been deleted since detection)
   832				continue
   833			}
   834	
   835			changes = append(changes, TreeChange{
   836				Path: relPath,
   837				Entry: &object.TreeEntry{
   838					Mode: mode,
   839					Hash: blobHash,
   840				},
   841			})
   842		}
   843	
   844		// Metadata directory files
   845		if metadataDir != "" && metadataDirAbs != "" {
   846			metadataRel, relErr := normalizeRepoRelativeTreePath(repoRoot, metadataDir)
   847			if relErr != nil {
   848				logInvalidGitTreePath(ctx, "add metadata directory", metadataDir, relErr)
   849			} else {
   850				metaChanges, metaErr := addDirectoryToChanges(ctx, s.repo, repoRedactCache(ctx, s.repo), metadataDirAbs, metadataRel)
   851				if metaErr != nil {
   852					return plumbing.ZeroHash, fmt.Errorf("failed to add metadata directory: %w", metaErr)
   853				}
   854				changes = append(changes, metaChanges...)
   855			}
   856		}
   857	
   858		return ApplyTreeChanges(ctx, s.repo, baseTreeHash, changes)
   859	}
