   864	// FlattenTree recursively flattens a tree into a map of full paths to entries.
   865	func FlattenTree(repo *git.Repository, tree *object.Tree, prefix string, entries map[string]object.TreeEntry) error {
   866		for _, entry := range tree.Entries {
