  1051	// insertIntoTree inserts a file entry into the tree structure.
  1052	func insertIntoTree(node *treeNode, pathParts []string, entry object.TreeEntry) {
  1053		if len(pathParts) == 1 {
  1054			// This is a file in the current directory
  1055			node.files = append(node.files, object.TreeEntry{
  1056				Name: pathParts[0],
  1057				Mode: entry.Mode,
  1058				Hash: entry.Hash,
  1059			})
  1060			return
  1061		}
  1062	
  1063		// This is in a subdirectory
  1064		dirName := pathParts[0]
  1065		if node.entries[dirName] == nil {
  1066			node.entries[dirName] = &treeNode{
  1067				entries: make(map[string]*treeNode),
  1068				files:   []object.TreeEntry{},
  1069			}
  1070		}
  1071		insertIntoTree(node.entries[dirName], pathParts[1:], entry)
  1072	}
