  1074	// buildTreeObject recursively builds tree objects from a treeNode.
  1075	func buildTreeObject(repo *git.Repository, node *treeNode) (plumbing.Hash, error) {
  1076		var treeEntries []object.TreeEntry
  1077	
  1078		// Add files
  1079		treeEntries = append(treeEntries, node.files...)
  1080	
  1081		// Recursively build subtrees
  1082		for name, subnode := range node.entries {
  1083			subHash, err := buildTreeObject(repo, subnode)
  1084			if err != nil {
  1085				return plumbing.ZeroHash, err
  1086			}
  1087			treeEntries = append(treeEntries, object.TreeEntry{
  1088				Name: name,
  1089				Mode: filemode.Dir,
  1090				Hash: subHash,
  1091			})
  1092		}
  1093	
  1094		// Sort entries (git requires sorted entries)
  1095		sortTreeEntries(treeEntries)
  1096	
  1097		// Create tree object
  1098		tree := &object.Tree{Entries: treeEntries}
  1099	
  1100		obj := repo.Storer.NewEncodedObject()
  1101		if err := tree.Encode(obj); err != nil {
  1102			return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
  1103		}
  1104	
  1105		hash, err := repo.Storer.SetEncodedObject(obj)
  1106		if err != nil {
  1107			return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
  1108		}
  1109	
  1110		return hash, nil
  1111	}
