  1113	// sortTreeEntries sorts tree entries in git's required order.
  1114	// Git sorts tree entries by name, with directories having a trailing /
  1115	func sortTreeEntries(entries []object.TreeEntry) {
  1116		sort.Slice(entries, func(i, j int) bool {
  1117			nameI := entries[i].Name
  1118			nameJ := entries[j].Name
  1119			if entries[i].Mode == filemode.Dir {
  1120				nameI += "/"
  1121			}
  1122			if entries[j].Mode == filemode.Dir {
  1123				nameJ += "/"
  1124			}
  1125			return nameI < nameJ
  1126		})
  1127	}
