297	// resolveRefMaybeFetch resolves a checkpoint ref, fetching it from the remote
298	// once when it is missing locally and a ref fetcher is configured (the
299	// checkpoint may have been written on another machine). It distinguishes a
300	// genuinely absent ref (returns a plumbing.ErrReferenceNotFound-wrapped error,
301	// which callers map to ErrCheckpointNotFound) from a real failure — an IO error,
302	// or a fetch that failed for network/context reasons — which is returned as-is
303	// so it is not silently swallowed as "checkpoint not found".
304	func (s *gitRefsStore) resolveRefMaybeFetch(ctx context.Context, cid id.CheckpointID) (*plumbing.Reference, error) {
305		refName, err := RefName(cid)
306		if err != nil {
307			return nil, err
308		}
309		ref, err := s.repo.Reference(refName, true)
310		if err == nil {
311			return ref, nil
312		}
313		if !errors.Is(err, plumbing.ErrReferenceNotFound) {
314			return nil, fmt.Errorf("resolve checkpoint ref %s: %w", refName, err)
315		}
316		if s.refFetcher == nil {
317			return nil, err //nolint:wrapcheck // genuinely absent; caller maps ErrReferenceNotFound to ErrCheckpointNotFound
318		}
319		s.fetchFailureMu.Lock()
320		priorFailure := s.fetchFailure
321		s.fetchFailureMu.Unlock()
322		if priorFailure != nil {
323			// Note the cause may name a DIFFERENT ref — it is the first failure
324			// of this operation, remembered so the outage is paid once.
325			return nil, fmt.Errorf("fetch checkpoint ref %s: skipped, an earlier checkpoint-ref fetch already failed in this operation: %w", refName, priorFailure)
326		}
327		if fetchErr := s.refFetcher(ctx, refName); fetchErr != nil {
328			if errors.Is(fetchErr, plumbing.ErrReferenceNotFound) {
329				// The fetcher probed the remote and it genuinely lacks this ref
330				// (remote.FetchCheckpointRef's absence signal) — absence, not a
331				// failure, and per-ref, so it is not memoized.
332				logging.Debug(ctx, "git-refs: remote has no such checkpoint ref",
333					slog.String("ref", refName.String()))
334				return nil, plumbing.ErrReferenceNotFound
335			}
336			// Memoize only network verdicts: a cancellation originating from the
337			// CALLER's context says nothing about the remote and must not poison
338			// later fetches on this store.
339			if ctx.Err() == nil {
340				s.fetchFailureMu.Lock()
341				if s.fetchFailure == nil {
342					s.fetchFailure = fetchErr
343				}
344				s.fetchFailureMu.Unlock()
345			}
346			logging.Debug(ctx, "git-refs: on-demand checkpoint ref fetch failed",
347				slog.String("ref", refName.String()), slog.String("error", fetchErr.Error()))
348			return nil, fmt.Errorf("fetch checkpoint ref %s: %w", refName, fetchErr)
349		}
350		// Re-resolve after a successful fetch. ErrReferenceNotFound here means the
351		// remote genuinely has no such checkpoint; anything else is a real error.
352		ref, err = s.repo.Reference(refName, true)
353		if err != nil {
354			return nil, err //nolint:wrapcheck // ErrReferenceNotFound (absent) or a real error; caller distinguishes via errors.Is
355		}
356		return ref, nil
357	}
