 17	// Write dispatches a persistent write request to the matching git operation.
 18	// The request types and Writer interface are defined in the api/checkpoint
 19	// contract (re-exported here via aliases). Unknown request types are a
 20	// programmer error, surfaced rather than ignored.
 21	func (s *GitStore) Write(ctx context.Context, req WriteRequest) error {
 22		return dispatchPersistentWrite(ctx, s, req)
 23	}
