161	// attribution on the checkpoint's current subtree, returning the new subtree
162	// hash. Returns ErrCheckpointNotFound when the checkpoint has no root summary.
163	func (s *treeWriter) applyAttributionBackfill(ctx context.Context, existing *object.Tree, basePath string, combinedAttribution *Attribution) (plumbing.Hash, error) {
164		entries, err := s.flattenExisting(existing, basePath)
