   313	func replaceDataFreeMetadataRef(ctx context.Context, repo *git.Repository, refName plumbing.ReferenceName, hash plumbing.Hash) (bool, error) {
   314		changed := false
   315		_, err := checkpoint.RunRefTransaction(ctx, repo, refName, func(current plumbing.Hash) (plumbing.Hash, bool, error) {
   316			changed = false
   317			if current == hash {
   318				return current, false, nil
   319			}
   320			if !current.IsZero() {
