   360	func checkpointInfosFromCommitted(committed []checkpoint.CheckpointInfo) []CheckpointInfo {
   361		result := make([]CheckpointInfo, 0, len(committed))
   362		for _, c := range committed {
   363			result = append(result, CheckpointInfo{
   364				CheckpointID:     c.CheckpointID,
   365				SessionID:        c.SessionID,
   366				CreatedAt:        c.CreatedAt,
   367				CheckpointsCount: c.CheckpointsCount,
   368				FilesTouched:     c.FilesTouched,
   369				Agent:            c.Agent,
