   372				SessionCount:     c.SessionCount,
   373				SessionIDs:       c.SessionIDs,
   374				Imported:         c.Imported,
   375			})
   376		}
   377		sort.Slice(result, func(i, j int) bool {
   378			return result[i].CreatedAt.After(result[j].CreatedAt)
