   257	func hasReachableShallowBoundary(ctx context.Context, repo *git.Repository, repoPath string, hashes ...string) (bool, error) {
   258		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
   259		defer cancel()
   260	
   261		shallowHashes, err := repo.Storer.Shallow()
   262		if err != nil {
   263			return false, fmt.Errorf("read shallow commits: %w", err)
   264		}
   265		if len(shallowHashes) == 0 {
   266			return false, nil
   267		}
   268	
   269		shallowCommits := make(map[string]struct{}, len(shallowHashes))
   270		for _, hash := range shallowHashes {
   271			shallowCommits[hash.String()] = struct{}{}
   272		}
   273		for _, hash := range hashes {
   274			reachesBoundary, err := historyReachesShallowBoundary(ctx, repoPath, hash, shallowCommits)
   275			if err != nil {
   276				return false, err
   277			}
   278			if reachesBoundary {
   279				return true, nil
   280			}
   281		}
   282		return false, nil
   283	}
