 73	func concurrentSession(checkpointID id.CheckpointID, sessionID string) Session {
 74		return Session{
 75			CheckpointID: checkpointID,
 76			SessionID:    sessionID,
 77			Strategy:     "manual-commit",
 78			Transcript:   redact.AlreadyRedacted([]byte(sessionID + " transcript\n")),
 79			Prompts:      []string{"do the work"},
 80			FilesTouched: []string{sessionID + ".go"},
 81			AuthorName:   "Test Author",
 82			AuthorEmail:  "test@example.com",
 83		}
 84	}
